"232\" y=\"62\" width=\"44\" height=\"34\" rx=\"6\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"254\" y=\"87\" fill=\"currentColor\" font-size=\"20\" font-weight=\"bold\" text-anchor=\"middle\">C</text><rect x=\"232\" y=\"100\" width=\"44\" height=\"34\" rx=\"6\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"254\" y=\"125\" fill=\"currentColor\" font-size=\"20\" font-weight=\"bold\" text-anchor=\"middle\">G</text><g fill=\"currentColor\" font-size=\"15\"><text x=\"20\" y=\"30\">1. zincir</text><text x=\"20\" y=\"176\">2. zincir</text></g></svg>",
